import type { Metadata } from "next";
import { Montserrat, Bodoni_Moda, Playfair_Display, Lato } from "next/font/google";
import localFont from "next/font/local";
import { Toaster } from "sonner";
import "./globals.css";
import { CurrencyProvider } from "@/lib/contexts/CurrencyContext";

const montserrat = Montserrat({
  variable: "--font-sans",
  subsets: ["latin"],
  display: "swap",
});

const bodoni = Bodoni_Moda({
  variable: "--font-serif",
  subsets: ["latin"],
  display: "swap",
});

const playfair = Playfair_Display({
  variable: "--font-playfair",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700"],
  display: "swap",
});

const lato = Lato({
  variable: "--font-lato",
  subsets: ["latin"],
  weight: ["300"],
  display: "swap",
});

const megante = localFont({
  src: "../../public/fonts/Megante.woff",
  variable: "--font-megante",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Kofa Beauty",
  description: "Confidence, not comparison",
};


export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" suppressHydrationWarning>
      <body 
        className={`${montserrat.variable} ${bodoni.variable} ${megante.variable} ${playfair.variable} ${lato.variable} font-sans antialiased`}
        suppressHydrationWarning
      >
        <CurrencyProvider>
          {children}
          <Toaster />
        </CurrencyProvider>
      </body>
    </html>
  );
}
